<?php
require __DIR__.'/../config/app.php';
$me=require_role('admin');$pageTitle='Admin Dashboard';$bodyClass='dashboard-page admin-page';$activePage='dashboard';
$categories=['cultural'=>'Cultural','technical'=>'Technical','sports'=>'Sports','volunteer'=>'Volunteer'];
$colors=['cultural'=>'#9063e8','technical'=>'#51a8e8','sports'=>'#40c49d','volunteer'=>'#f3b84b'];
try{
    $pdo=db();
    $totalEvents=(int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn();
    $totalApplications=(int)$pdo->query('SELECT COUNT(*) FROM event_applications')->fetchColumn();
    $volunteerCount=(int)$pdo->query("SELECT COUNT(DISTINCT user_id) FROM volunteer_applications WHERE status='Approved'")->fetchColumn();
    $studentCount=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student' AND is_active=1")->fetchColumn();
    $allEvents=all_events();$events=array_slice($allEvents,0,7);
    $apps=$pdo->query('SELECT a.status,a.applied_at,e.title,u.name FROM event_applications a JOIN events e ON e.id=a.event_id JOIN users u ON u.id=a.user_id ORDER BY a.applied_at DESC LIMIT 5')->fetchAll();
    $activity=$pdo->query("SELECT 'event' AS kind,e.created_at AS occurred_at,e.title,u.name AS actor FROM events e LEFT JOIN users u ON u.id=e.created_by UNION ALL SELECT 'application' AS kind,a.applied_at AS occurred_at,e.title,u.name AS actor FROM event_applications a JOIN events e ON e.id=a.event_id JOIN users u ON u.id=a.user_id ORDER BY occurred_at DESC LIMIT 5")->fetchAll();
}catch(Throwable $t){$totalEvents=$totalApplications=$volunteerCount=$studentCount=0;$allEvents=$events=$apps=$activity=[];}
$trend=array_fill_keys(array_keys($categories),array_fill(0,7,0));$chartLabels=[];$chartDates=[];for($i=6;$i>=0;$i--){$day=strtotime('-'.$i.' days');$chartLabels[]=date('d M',$day);$chartDates[]=date('Y-m-d',$day);}try{$q=db()->query('SELECT category,DATE(created_at) activity_date,COUNT(*) total FROM events WHERE created_at>=CURRENT_DATE - INTERVAL 6 DAY GROUP BY category,DATE(created_at)');foreach($q->fetchAll() as $row){$dayIndex=array_search($row['activity_date'],$chartDates,true);$slug=strtolower($row['category']);if($dayIndex!==false&&isset($trend[$slug]))$trend[$slug][$dayIndex]=(int)$row['total'];}}catch(Throwable $t){}$chartMax=max(5,(int)(ceil(max(array_merge(...array_values($trend)))/5)*5));$series=[];foreach($categories as $slug=>$label){$coords=[];foreach($trend[$slug] as $i=>$value){$coords[]=['x'=>55+$i*(550/6),'y'=>175-($value/$chartMax)*130];}$path='';foreach($coords as $i=>$point){if($i===0){$path='M '.round($point['x'],1).' '.round($point['y'],1);continue;}$prev=$coords[$i-1];$before=$coords[max(0,$i-2)];$next=$coords[min(count($coords)-1,$i+1)];$dx=$point['x']-$prev['x'];$c1x=$prev['x']+$dx/3;$c1y=$prev['y']+($point['y']-$before['y'])/6;$c2x=$point['x']-$dx/3;$c2y=$point['y']-($next['y']-$prev['y'])/6;$path.=' C '.round($c1x,1).' '.round($c1y,1).', '.round($c2x,1).' '.round($c2y,1).', '.round($point['x'],1).' '.round($point['y'],1);}$series[$slug]=['path'=>$path,'coords'=>$coords];}
$categoryCounts=array_fill_keys(array_keys($categories),0);foreach($allEvents as $event){$slug=strtolower($event['category']);if(isset($categoryCounts[$slug]))$categoryCounts[$slug]++;}
$totalChartEvents=array_sum($categoryCounts);$stops=[];$start=0;foreach($categoryCounts as $slug=>$count){$end=$start+($totalChartEvents?100*$count/$totalChartEvents:25);$stops[]=$colors[$slug].' '.round($start,2).'% '.round($end,2).'%';$start=$end;}$donut='conic-gradient('.implode(',',$stops).')';
require __DIR__.'/../includes/header.php';
?>
<div class="dash-layout admin-layout">
<?php require __DIR__.'/../includes/sidebar.php';?>
<main class="dash-main">
    <section class="welcome-banner admin-welcome"><div><h1>Hello, Admin</h1><p>Welcome back! Here's what's happening at<br>Marwadi University EventHub.</p></div><div class="banner-campus"><div class="building"><img class="building-photo" src="<?=url('assets/images/campus-reference.jpg')?>" alt="Marwadi University campus"><div class="building-sign"><br>Marwadi<br>University</div></div></div></section>
    <div class="stat-grid">
    <?php foreach([['calendar','Total Events',$totalEvents,'cyan'],['clipboard','Total Applications',$totalApplications,'mint'],['people','Registered Volunteers',$volunteerCount,'violet'],['user','Total Students',$studentCount,'pink']] as $stat):?><div class="stat-card <?=$stat[3]?>"><span><?=eventhub_icon($stat[0])?></span><div><small><?=$stat[1]?></small><b><?=$stat[2]?></b><em>Current records</em></div></div><?php endforeach;?>
    </div>
    <div class="admin-grid">
        <section class="dash-panel overview-panel"><div class="section-heading"><h2><span class="dash-heading-icon cyan-icon"><?=eventhub_icon('calendar')?></span>Events Overview</h2><span>Last 7 Days</span></div><div class="chart-legend"><?php foreach($categories as $slug=>$label):?><span><i style="background:<?=$colors[$slug]?>"></i><?=$label?></span><?php endforeach;?></div><svg class="overview-chart" viewBox="0 0 640 220" role="img" aria-label="Number of events created each day by category for the last seven days"><g class="chart-grid"><?php for($i=0;$i<6;$i++):$y=45+$i*26;?><line x1="48" y1="<?=$y?>" x2="620" y2="<?=$y?>"/><text x="10" y="<?=$y+4?>"><?=round($chartMax*(5-$i)/5)?></text><?php endfor;?></g><?php foreach($series as $slug=>$data):if(array_sum($trend[$slug])>0):?><path d="<?=$data['path']?>" fill="none" stroke="<?=$colors[$slug]?>" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><?php foreach($data['coords'] as $i=>$point):?><circle cx="<?=round($point['x'],1)?>" cy="<?=round($point['y'],1)?>" r="3.5" fill="<?=$colors[$slug]?>"><title><?=e($categories[$slug])?> · <?=e($chartLabels[$i])?>: <?=$trend[$slug][$i]?> event<?=$trend[$slug][$i]===1?'':'s'?></title></circle><?php endforeach;?><?php endif;endforeach;?><?php foreach($chartLabels as $i=>$label):$x=55+$i*(550/6);?><text class="chart-date" x="<?=$x?>" y="207" text-anchor="middle"><?=e($label)?></text><?php endforeach;?><?php if(array_sum(array_merge(...array_values($trend)))===0):?><text x="335" y="112" text-anchor="middle" class="chart-empty">No events created in the last 7 days</text><?php endif;?></svg></section>
        <section class="dash-panel category-panel"><div class="section-heading"><h2><span class="dash-heading-icon violet-icon"><?=eventhub_icon('trophy')?></span>Event Categories</h2></div><div class="category-layout"><div class="category-donut" style="background:<?=$donut?>"><div><b><?=$totalEvents?></b><small>Total Events</small></div></div><div class="category-list"><?php foreach($categories as $slug=>$label):?><p><span class="dot <?=e($slug)?>" style="background:<?=$colors[$slug]?>"></span><?=e($label)?><b><?=($totalChartEvents?round(100*$categoryCounts[$slug]/$totalChartEvents):0)?>%</b></p><?php endforeach;?></div></div></section>
        <section class="dash-panel applications-panel"><div class="section-heading"><h2><span class="dash-heading-icon cyan-icon"><?=eventhub_icon('clipboard')?></span>Recent Event Applications</h2><a href="<?=url('admin/applications.php')?>">View All</a></div><div class="application-table"><div class="application-head"><span>Student Name</span><span>Event Name</span><span>Applied On</span><span>Status</span></div><?php foreach($apps as $application):?><div class="application-data"><span class="admin-app-user"><i><?=e(initials($application['name']))?></i><?=e($application['name'])?></span><span><?=e($application['title'])?></span><span><?=date('d M Y',strtotime($application['applied_at']))?></span><span class="pill <?=strtolower(e($application['status']))?>"><?=e($application['status'])?></span></div><?php endforeach;?><?php if(!$apps):?><p class="muted">Applications will appear here when students apply.</p><?php endif;?></div></section>
        <div class="admin-actions-stack"><section class="dash-panel actions-panel"><div class="section-heading"><h2><span class="dash-heading-icon mint-icon"><?=eventhub_icon('people')?></span>Quick Actions</h2></div><div class="quick-grid"><a href="<?=url('admin/events.php?action=create')?>"><b class="cyan-icon"><?=eventhub_icon('calendar')?></b>Add New Event </a><a href="<?=url('admin/volunteers.php')?>"><b class="mint-icon"><?=eventhub_icon('people')?></b>Manage Volunteers </a><a href="<?=url('admin/cultural.php?action=create')?>"><b class="violet-icon"><?=eventhub_icon('music')?></b>Create Cultural Activity </a><a href="<?=url('admin/reports.php')?>"><b class="blue-icon"><?=eventhub_icon('chart')?></b>View Reports </a></div></section><section class="admin-promo"><b>Plan Events<br>Build Opportunities<br>Create Impact</b></section></div>
    </div>
</main>
<aside class="dash-right"><section class="dash-panel"><div class="section-heading"><h3><span class="dash-heading-icon cyan-icon"><?=eventhub_icon('calendar')?></span>Upcoming Events</h3><a href="<?=url('admin/events.php')?>">View All</a></div><?php foreach(array_slice($events,0,4) as $event):?><div class="mini-event"><img src="<?=e(image_source($event))?>" data-fallback="<?=url(image_for($event))?>" onerror="this.onerror=null;this.src=this.dataset.fallback" alt=""><b><?=e($event['title'])?><small><?=date('d M Y',strtotime($event['event_date']))?> · <?=e($event['venue'])?></small></b></div><?php endforeach;?></section><section class="dash-panel"><div class="section-heading"><h3><span class="dash-heading-icon cyan-icon"><?=eventhub_icon('calendar')?></span>Recent Activity</h3><a href="<?=url('admin/applications.php')?>">View All</a></div><?php foreach($activity as $item):?><div class="activity-item"><span class="activity-dot"><?=eventhub_icon($item['kind']==='event'?'calendar':'people')?></span><b><?=$item['kind']==='event'?'New event added':'Application received'?>: <?=e($item['title'])?><small><?=e($item['actor'])?> · <?=date('g:i A · d M',strtotime($item['occurred_at']))?></small></b></div><?php endforeach;?><?php if(!$activity):?><p class="muted">Activity appears as events are created and students apply.</p><?php endif;?></section></aside>
</div>
<?php require __DIR__.'/../includes/footer.php';
